package com.mitcampus.ams.exception;
import com.mitcampus.ams.dto.ApiResponse;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) ApiResponse notFound(Exception e){return ApiResponse.fail(e.getMessage());}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) ApiResponse invalid(Exception e){return ApiResponse.fail(e instanceof MethodArgumentNotValidException?"Please correct the highlighted fields.":e.getMessage());}@ExceptionHandler(SecurityException.class) @ResponseStatus(HttpStatus.FORBIDDEN) ApiResponse denied(Exception e){return ApiResponse.fail(e.getMessage());}@ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) ApiResponse error(Exception e){return ApiResponse.fail("An unexpected server error occurred.");}}
